#include <future>
#include <thread>
#include <system_error>
#include <cassert>
#include <type_traits>
#include <utility>

int main() {
    std::promise<int> promise;
    std::promise<int> other;
    other = std::move(promise);
    other.swap(promise);
    std::swap(other, promise);
    auto future = other.get_future();
    other.set_value(7);
    std::future<int> moved;
    moved = std::move(future);
    auto shared = moved.share();
    std::shared_future<int> copy;
    copy = shared;
    assert(copy.wait_until(std::chrono::steady_clock::now() +
               std::chrono::seconds(1)) == std::future_status::ready);
    assert(copy.get() == 7);
    std::packaged_task<int()> task{[] { return 9; }};
    assert(task.valid());
    auto result = task.get_future();
    std::packaged_task<int()> transfer;
    transfer = std::move(task);
    transfer.swap(task);
    std::swap(transfer, task);
    transfer();
    assert(result.get() == 9);
    auto deferred = std::async(std::launch::deferred, [] { return 3; });
    assert(deferred.get() == 3);
    std::future_error error{std::future_errc::broken_promise};
    std::future_error errorCopy = error;
    errorCopy = error;
    assert(error.code() == std::make_error_code(std::future_errc::broken_promise));
    assert(*error.what());
    static_assert(std::is_error_code_enum<std::future_errc>::value);
    assert(std::make_error_condition(std::future_errc::broken_promise).category() ==
        std::future_category());
    static_assert(std::uses_allocator<std::promise<int>, std::allocator<int>>::value);

    std::promise<int> exceptional;
    auto failure = exceptional.get_future();
    std::thread worker([p = std::move(exceptional)]() mutable {
        p.set_exception_at_thread_exit(
            std::make_exception_ptr(std::runtime_error("failed")));
    });
    worker.join();
    try {
        (void)failure.get();
        assert(false);
    } catch (const std::runtime_error &) {
    }
}
